                const band = bandFor(chosen.ref.st);
                const high = band.dpHigh.reconstruct(chosen.ref.bA, chosen.ref.eH, chosen.ref.HA);
                const low = band.dpLow.reconstruct(kLocal - chosen.ref.bA, chosen.ref.eL, chosen.ref.sLow);
