        // Name nebeneinander) - ein Treffer in irgendeiner Form genuegt.
        const norm = v => String(v == null ? '' : v).toUpperCase().trim();
        const keysOf = v => (Array.isArray(v) ? v : [v]).map(norm).filter(Boolean);
