            while ((m = br.exec(head)) !== null) { const v = galleryNum(m[1]); if (v > 0) bins.push(v); }
            const sales = []; const sr = /<div[^>]*>([A-Z][a-z]{2} \d{1,2}, \d{2}:\d{2})<\/div>\s*<div[^>]*>([\d,]+)<\/div>/g;
